-- Run this with a Snowflake role that can create views. The agent's role is read-only and cannot.
CREATE OR REPLACE VIEW <DATABASE>.<SCHEMA>.ORDERS_ANALYSIS AS
SELECT b.*, j0.C_NAME AS C_NAME, j0.C_ADDRESS AS C_ADDRESS, j0.C_NATIONKEY AS C_NATIONKEY, j0.C_PHONE AS C_PHONE, j0.C_ACCTBAL AS C_ACCTBAL, j0.C_MKTSEGMENT AS C_MKTSEGMENT, j0.C_COMMENT AS C_COMMENT, COALESCE(r0.LINE_COUNT, 0) AS LINE_COUNT, COALESCE(r0.TOTAL_QUANTITY, 0) AS TOTAL_QUANTITY, COALESCE(r0.TOTAL_EXTENDED_PRICE, 0) AS TOTAL_EXTENDED_PRICE, COALESCE(r0.TOTAL_NET_REVENUE, 0) AS TOTAL_NET_REVENUE, r0.AVG_DISCOUNT AS AVG_DISCOUNT, COALESCE(r0.RETURNED_LINE_COUNT, 0) AS RETURNED_LINE_COUNT, COALESCE(r0.OPEN_LINE_COUNT, 0) AS OPEN_LINE_COUNT, COALESCE(r0.LATE_LINE_COUNT, 0) AS LATE_LINE_COUNT, COALESCE(r0.AIR_LINE_COUNT, 0) AS AIR_LINE_COUNT, r0.LAST_SHIP_DATE AS LAST_SHIP_DATE, r0.LAST_RECEIPT_DATE AS LAST_RECEIPT_DATE
FROM (SELECT t.*, IFF(O_ORDERSTATUS = 'O', 1, 0) AS IS_OPEN, IFF(O_ORDERSTATUS = 'F', 1, 0) AS IS_FULFILLED, IFF(O_ORDERSTATUS = 'P', 1, 0) AS IS_PARTIAL, IFF(O_ORDERPRIORITY IN ('1-URGENT', '2-HIGH'), 1, 0) AS IS_HIGH_PRIORITY, YEAR(O_ORDERDATE) AS ORDER_YEAR, DATE_TRUNC('month', O_ORDERDATE) AS ORDER_MONTH FROM SNOWFLAKE_SAMPLE_DATA.TPCH_SF1.ORDERS t) b
LEFT JOIN SNOWFLAKE_SAMPLE_DATA.TPCH_SF1.CUSTOMER j0 ON b.O_CUSTKEY = j0.C_CUSTKEY
LEFT JOIN (SELECT L_ORDERKEY AS K, COUNT(*) AS LINE_COUNT, SUM(L_QUANTITY) AS TOTAL_QUANTITY, SUM(L_EXTENDEDPRICE) AS TOTAL_EXTENDED_PRICE, SUM(L_EXTENDEDPRICE * (1 - L_DISCOUNT)) AS TOTAL_NET_REVENUE, AVG(L_DISCOUNT) AS AVG_DISCOUNT, COUNT_IF(L_RETURNFLAG = 'R') AS RETURNED_LINE_COUNT, COUNT_IF(L_LINESTATUS = 'O') AS OPEN_LINE_COUNT, COUNT_IF(L_RECEIPTDATE > L_COMMITDATE) AS LATE_LINE_COUNT, COUNT_IF(L_SHIPMODE IN ('AIR', 'REG AIR')) AS AIR_LINE_COUNT, MAX(L_SHIPDATE) AS LAST_SHIP_DATE, MAX(L_RECEIPTDATE) AS LAST_RECEIPT_DATE FROM SNOWFLAKE_SAMPLE_DATA.TPCH_SF1.LINEITEM GROUP BY L_ORDERKEY) r0 ON b.O_ORDERKEY = r0.K;
-- The agent's role must be able to read the view, or it will not see it:
GRANT SELECT ON VIEW <DATABASE>.<SCHEMA>.ORDERS_ANALYSIS TO ROLE <READ_ONLY_ROLE>;
